  const invalidOperator = "Invalid operator";
  const divisionByZeroMessage = "Division by zero is not allowed";
  let operationSuccess = true;
  const validOperators = ['+', '-', '*', '/'];

  if (!validOperators.includes(operationSymbol)) {
    console.log(invalidOperator);
    return null;
  }

  switch (operationSymbol) {
    case '+':
      resultValue = firstNumber + secondNumber;
      break;
    case '-':
      resultValue = firstNumber - secondNumber;
      break;
    case '*':
      resultValue = firstNumber * secondNumber;
      break;
    case '/':
      if (secondNumber === 0) {
        console.log(divisionByZeroMessage);
        return null;
      }
      resultValue = firstNumber / secondNumber;
      break;
    default:
      operationSuccess = false;
      break;
  }

  if (operationSuccess) {
    let finalAnswer = resultValue;
    return finalAnswer;
  } else {
    return null;
  }
}

